def publish_existing_report_cards(apps, schema_editor):
    """
    Report cards generated before the publish step existed were already visible
    to students, so keep them visible. New ones start as drafts.
    """
    Snapshot = apps.get_model("mainApp", "ReportCardSnapshot")
    Snapshot.objects.filter(is_latest=True).exclude(pdf="").exclude(pdf__isnull=True).update(is_published=True)



